INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-31','MAP','reading','mcq',2,'Mira kept a small notebook in her backpack. Every evening she wrote down one thing she had noticed that day: a spider finishing its web, the way the bus driver hummed, a cloud shaped like a boot. "Small things add up," she told her brother. By June the notebook was full, and Mira realized that she had never once felt bored all year.','What is the main idea of the passage?',NULL,'["Mira dislikes riding the bus.","Paying attention to small details can make life more interesting.","Spiders are important to the school year.","Mira wants to become a bus driver."]',1,'The notebook habit kept Mira from feeling bored.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-32','MAP','reading','mcq',3,'Mira kept a small notebook in her backpack. Every evening she wrote down one thing she had noticed that day: a spider finishing its web, the way the bus driver hummed, a cloud shaped like a boot. "Small things add up," she told her brother. By June the notebook was full, and Mira realized that she had never once felt bored all year.','What does the word "realized" mean as used in the passage?',NULL,'["forgot","suddenly understood","argued","wished"]',1,'"Realized" means came to understand.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-33','MAP','reading','mcq',3,'Mira kept a small notebook in her backpack. Every evening she wrote down one thing she had noticed that day: a spider finishing its web, the way the bus driver hummed, a cloud shaped like a boot. "Small things add up," she told her brother. By June the notebook was full, and Mira realized that she had never once felt bored all year.','Which detail best supports the idea that Mira was observant?',NULL,'["She carried a backpack.","She talked to her brother.","She wrote down things like a cloud shaped like a boot.","The notebook was full by June."]',2,'Noticing odd details shows she is observant.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-34','MAP','reading','mcq',3,'Honeybees communicate through movement. When a scout bee finds flowers, she returns to the hive and performs a "waggle dance." The angle of the dance shows the direction of the flowers relative to the sun, and the length of the waggle shows how far away they are. Other bees watch closely and then fly straight to the food.','According to the passage, what does the length of the waggle tell other bees?',NULL,'["The type of flower","How far away the flowers are","The time of day","The size of the hive"]',1,'Length shows distance.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-35','MAP','reading','mcq',4,'Honeybees communicate through movement. When a scout bee finds flowers, she returns to the hive and performs a "waggle dance." The angle of the dance shows the direction of the flowers relative to the sun, and the length of the waggle shows how far away they are. Other bees watch closely and then fly straight to the food.','Which sentence best describes how the passage is organized?',NULL,'["It compares two kinds of insects.","It tells a story in time order.","It explains how a behavior works.","It argues that bees are better than ants."]',2,'The passage explains the waggle dance.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-36','MAP','reading','mcq',4,'Honeybees communicate through movement. When a scout bee finds flowers, she returns to the hive and performs a "waggle dance." The angle of the dance shows the direction of the flowers relative to the sun, and the length of the waggle shows how far away they are. Other bees watch closely and then fly straight to the food.','What can the reader infer about the bees that watch the dance?',NULL,'["They cannot fly.","They use the information to find food.","They are guards of the hive.","They dislike the scout."]',1,'They fly straight to the food afterwards.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-37','MAP','reading','mcq',4,'The lighthouse keeper had not spoken to another person in three weeks. When the supply boat finally appeared, he waved so wildly that his hat sailed into the sea. He laughed, and the sound surprised him; it was rusty, like a door that had not been opened in years.','The comparison of his laugh to "a door that had not been opened in years" suggests that his laugh was',NULL,'["loud and angry","unused and a little strange","quiet and sad","quick and nervous"]',1,'A rusty door = unused.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-38','MAP','reading','mcq',5,'The lighthouse keeper had not spoken to another person in three weeks. When the supply boat finally appeared, he waved so wildly that his hat sailed into the sea. He laughed, and the sound surprised him; it was rusty, like a door that had not been opened in years.','Which word best describes the keeper when the boat arrived?',NULL,'["indifferent","overjoyed","suspicious","embarrassed"]',1,'Wild waving and laughing show joy.',1,0);
